class Solution {
public:
    int minOperations(vector<int>& nums, int k) {
        priority_queue<long long, vector<long long>, greater<long long>> pq(nums.begin(), nums.end());
        int ops = 0;
        while (pq.size() >= 2 && pq.top() < k) {
            long long x = pq.top(); pq.pop();
            long long y = pq.top(); pq.pop();
            pq.push(x * 2LL + y);
            ops++;
        }
        return ops;
    }
};

class Solution {
    public int minOperations(int[] nums, int k) {
        PriorityQueue<Long> pq = new PriorityQueue<>();
        for (int x : nums) pq.offer((long) x);
        int ops = 0;
        while (pq.size() >= 2 && pq.peek() < k) {
            long x = pq.poll();
            long y = pq.poll();
            pq.offer(x * 2L + y);
            ops++;
        }
        return ops;
    }
}

var minOperations = function(nums, k) {
    // Simple binary min-heap implementation
    const heap = [];
    const push = (val) => {
        heap.push(val);
        let i = heap.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (heap[p] <= heap[i]) break;
            [heap[p], heap[i]] = [heap[i], heap[p]];
            i = p;
        }
    };
    const pop = () => {
        const top = heap[0];
        const bottom = heap.pop();
        if (heap.length > 0) {
            heap[0] = bottom;
            let i = 0;
            while ((i << 1) + 1 < heap.length) {
                let left = (i << 1) + 1, right = left + 1, best = left;
                if (right < heap.length && heap[right] < heap[left]) best = right;
                if (heap[i] <= heap[best]) break;
                [heap[i], heap[best]] = [heap[best], heap[i]];
                i = best;
            }
        }
        return top;
    };
    for (const x of nums) push(BigInt(x));
    let ops = 0;
    const target = BigInt(k);
    while (heap.length >= 2 && heap[0] < target) {
        const x = pop();
        const y = pop();
        push(x * 2n + y);
        ops++;
    }
    return ops;
};
